export const DDA_INITIAL_DIGIMON_INDEX = DDA_INITIAL_EVOLUTION_DB.digimonIndex;
export const DDA_INITIAL_EVOLUTION_RELATIONS = DDA_INITIAL_EVOLUTION_DB.relations;
export const DDA_INITIAL_EVOLUTION_LOOKUPS = DDA_INITIAL_EVOLUTION_DB.lookups;
export const DDA_INITIAL_LINE_OPTIONS = DDA_INITIAL_EVOLUTION_DB.initialLineOptions;
export const DDA_INITIAL_EVOLUTION_QC = DDA_INITIAL_EVOLUTION_DB.qc;

export function getInitialDigimonById(id) {
  return DDA_INITIAL_DIGIMON_INDEX?.[id] ?? null;
}

export function getInitialEvolutionRelationsFrom(fromId, options = {}) {
  const {
    rank = null,
    toStageKey = null,
    includeNeedsReview = true
  } = options;

  const relationIds = DDA_INITIAL_EVOLUTION_LOOKUPS.relationsByFrom?.[fromId] ?? [];

  return relationIds
    .map((relationId) => DDA_INITIAL_EVOLUTION_RELATIONS.find((relation) => relation.id === relationId))
    .filter(Boolean)
    .filter((relation) => !rank || relation.rank === rank)
    .filter((relation) => !toStageKey || relation.toStageKey === toStageKey)
    .filter((relation) => includeNeedsReview || relation.curationStatus !== "needs_review");
}

export function getInitialEvolutionOptionsFrom(fromId, options = {}) {
  return getInitialEvolutionRelationsFrom(fromId, options).map((relation) => ({
    ...relation,
    digimon: getInitialDigimonById(relation.toId)
  }));
}

export function getBaby2OptionsForBaby1(baby1Id, options = {}) {
  return getInitialEvolutionOptionsFrom(baby1Id, {
    ...options,
    toStageKey: "baby2"
  });
}

export function getRookieOptionsForBaby2(baby2Id, options = {}) {
  return getInitialEvolutionOptionsFrom(baby2Id, {
    ...options,
    toStageKey: "child"
  });
}

export function getInitialLineOptionsForBaby1(baby1Id, options = {}) {
  const {
    includeAlternate = true,
    includeNeedsReview = true
  } = options;

  return DDA_INITIAL_LINE_OPTIONS
    .filter((line) => line.baby1Id === baby1Id)
    .filter((line) => includeAlternate || line.lineRank === "primary")
    .filter((line) => includeNeedsReview || line.curationStatus !== "needs_review")
    .map((line) => ({
      ...line,
      baby1: getInitialDigimonById(line.baby1Id),
      baby2: getInitialDigimonById(line.baby2Id),
      rookie: getInitialDigimonById(line.rookieId)
    }));
}
